        ["ما القميص المصنوع من آلاف الحلقات المعدنية الذي لبسه الفرسان؟","الزرد",["الدرع الصفائحي","العباءة","الصدرية"],"آلاف الحلقات متشابكة.","الزرد قميص من حلقات معدنية متشابكة.","قد يزن هذا القميص عشرة كيلوغرامات."],
        ["أي سلاح كان يقذف حجارة كبيرة على أسوار القلاع؟","المنجنيق",["المدفع","القوس والنشاب","الحربة"],"لا بارود، بل ذراع رافعة.","المنجنيق كان يقذف الحجارة فوق الأسوار أو عليها.","أحيانًا كانت تُقذف حيوانات نافقة فوق السور أيضًا."],
        ["لماذا كانت الفتحات الضيقة في أسوار القلاع؟","لإطلاق السهام منها",["للنظر إلى الخارج","للهواء النقي","للبريد"],"واسعة من الداخل وضيقة من الخارج.","فتحات السهام كانت ضيقة جدًا من الخارج حتى لا يصيب العدو من فيها.","تسمى أيضًا مرامي السهام."],
        ["ما هو شعار النبالة؟","علامة تدل على الفارس",["ترس خشبي","نوع خوذة","حامل سيف"],"لكل عائلة تصميمها.","شعار النبالة كان يبيّن إلى أي عائلة ينتمي الفارس.","علم دراسة الشعارات يسمى علم النبالة."],
        ["ما اسم مدوّنة الشرف التي كان على الفارس التزامها؟","الفروسية",["قوانين المدرسة","كتاب القانون","الخريطة"],"شجاع وصادق وحامٍ.","الفروسية تقول إن على الفارس أن يكون شجاعًا وفيًا مهذبًا.","الكلمة الأوروبية جاءت من كلمة الفارس على الحصان."],
        ["أي مرض قتل ثلث سكان أوروبا في العصور الوسطى؟","الطاعون",["الإنفلونزا","الحصبة","الحمى"],"يسمى أيضًا الموت الأسود.","ضرب الطاعون نحو عام 1350 وقتل ملايين الناس.","كانت تنقله البراغيث على الجرذان."]
