        ["أي أداة استعملها البحّارة لتحديد موقعهم بالنجوم؟","السدسية",["المنظار","البارومتر","ساعة الإيقاف"],"تقيس الزاوية بين نجم والأفق.","بالسدسية تقيس ارتفاع نجم أو الشمس.","من ذلك كان يمكن حساب خط العرض."],
        ["أي مرض أصاب البحّارة من نقص فيتامين C؟","الإسقربوط",["الطاعون","الإنفلونزا","الملاريا"],"الليمون كان ينفع ضده.","الإسقربوط سببه نقص فيتامين C.","كان البحّارة البريطانيون يشربون عصير الليمون الحامض."],
        ["أي طريق بحري إلى الهند وجده فاسكو دا غاما؟","حول إفريقيا",["فوق القطب الشمالي","عبر قناة بنما","برًا"],"عبر رأس الرجاء الصالح.","أبحر فاسكو دا غاما حول إفريقيا إلى الهند عام 1498.","لم تعد التوابل مضطرة للمجيء برًا."]
