        ["أي اختراع لفيليم أينتهوفن يقيس نبض قلبك؟","جهاز تخطيط القلب",["جهاز الأشعة السينية","السماعة الطبية","مقياس الحرارة"],"فاز هولندي بجائزة نوبل عنه.","اخترع أينتهوفن الجهاز الذي يرسم كهرباء قلبك: تخطيط القلب.","كان جهازه الأول يزن 270 كيلوغرامًا."],
        ["من تُعدّ أول مبرمجة حاسوب؟","آدا لوفلايس",["بيل غيتس","آلان تورينغ","ستيف جوبز"],"امرأة من القرن التاسع عشر.","كتبت آدا لوفلايس أول برنامج لآلة حاسبة عام 1843.","سُمّيت لغة برمجة باسمها: آدا."],
        ["أي هولندي صنع أول مجهر يُظهر البكتيريا؟","أنتوني فان ليوفنهوك",["كريستيان هويغنز","فيليم أينتهوفن","هندريك لورنتز"],"تاجر أقمشة من دلفت.","كان فان ليوفنهوك أول من رأى البكتيريا بعدساته المصنوعة يدويًا.","سمّاها «حُييّنات صغيرة»."],
        ["من اخترع الشبكة العنكبوتية العالمية؟","تيم بيرنرز لي",["مارك زوكربيرغ","إيلون ماسك","ستيف جوبز"],"كان يعمل في سيرن.","اخترع تيم بيرنرز لي الشبكة العنكبوتية العالمية عام 1989.","أهدى اختراعه للعالم مجانًا."],
        ["أي هولندي اخترع ساعة البندول؟","كريستيان هويغنز",["أنتوني فان ليوفنهوك","سيمون ستيفين","كورنيليس دريبل"],"اكتشف أيضًا قمر تيتان.","بنى هويغنز أول ساعة بندول دقيقة عام 1656.","كان خطأ ساعته عشر ثوانٍ فقط في اليوم."],
        ["ماذا اخترع الأخوان رايت؟","أول طائرة بمحرّك",["السيارة","القطار البخاري","المروحية"],"دامت رحلتهما الأولى 12 ثانية.","كان الأخوان رايت أول من طار بطائرة ذات محرّك عام 1903.","كانت أول رحلة أقصر من باع جناح طائرة بوينغ 747."]
