      natuur_energie: [
        ["ما العملية التي تصنع بها النباتات غذاءها من ضوء الشمس؟","التركيب الضوئي",["الاحتراق","التبخّر","التنفّس"],"«الضوئي» تعني الضوء.","في التركيب الضوئي تصنع النباتات السكر من الضوء والماء وثاني أكسيد الكربون.","وينتج عنه الأكسجين الذي نتنفسه."],
        ["أي مصدر طاقة يستعمل حرارة باطن الأرض؟","الطاقة الحرارية الأرضية",["الطاقة الشمسية","طاقة الرياح","الطاقة النووية"],"الاسم يشير إلى الأرض.","الطاقة الحرارية الأرضية تأخذ الحرارة من أعماق الأرض.","أيسلندا تدفّئ بها تقريبًا كل بيوتها."],
        ["ما هي ظاهرة الاحتباس الحراري؟","غازات تحبس الحرارة في الغلاف الجوي",["الشمس تزداد سخونة","البيوت الزجاجية تصنع الحرارة","الأرض تتقلّص"],"لولاها لكانت الأرض متجمدة.","غازات الدفيئة مثل ثاني أكسيد الكربون تحبس الحرارة كزجاج البيت الزجاجي.","الإفراط في هذه الغازات يجعل الأرض أدفأ مما ينبغي."],
        ["من أين تأتي طاقة توربين الرياح في الأصل؟","من الشمس",["من القمر","من الأرض","من البحر"],"الشمس تسخّن الهواء فيتحرك.","الريح تنشأ لأن الشمس تسخّن الهواء بشكل غير متساوٍ.","إذن الريح في الحقيقة شكل من الطاقة الشمسية."],
        ["ما الغاز الذي تستنشقه النباتات ونزفره نحن؟","ثاني أكسيد الكربون",["الأكسجين","الهيليوم","الهيدروجين"],"رمزه الكيميائي CO₂.","النباتات تأخذ ثاني أكسيد الكربون وتطلق الأكسجين.","الشجرة الكبيرة تمتص عشرات الكيلوغرامات منه في السنة."],
        ["ما هي الخلية الشمسية؟","لوح يحوّل الضوء إلى كهرباء",["مرآة","بطارية","مصباح"],"توضع على السطوح.","الخلية الشمسية تحوّل الضوء مباشرة إلى كهرباء.","استُعملت أولى الخلايا الشمسية على الأقمار الصناعية."],
        ["ماذا نسمي الكهرباء المصنوعة بالماء الساقط؟","الطاقة المائية",["الطاقة النووية","الغاز الحيوي","الغاز الطبيعي"],"الماء الساقط يدير توربينًا.","في الطاقة المائية يسقط الماء عبر توربين فيولّد الكهرباء.","النرويج تحصل على كل كهربائها تقريبًا من الطاقة المائية."],
        ["ما هو الغاز الحيوي؟","غاز من بقايا نباتية متعفّنة وروث",["غاز من باطن الأرض","غاز من البحر","غاز من الهواء"],"تصنعه البكتيريا.","البكتيريا تصنع الغاز الحيوي من الروث والنفايات الخضراء.","في بعض المزارع تعمل الجرارات بالغاز الحيوي."],
        ["أي مصدر طاقة ينفد؟","النفط",["الريح","الشمس","المد والجزر"],"إنه وقود أحفوري.","تكوّن النفط عبر ملايين السنين ولا يتجدد.","الريح والشمس والماء لا تنفد: فهي متجددة."],
        ["ما هي السلسلة الغذائية؟","من يأكل ماذا في الطبيعة",["سلسلة متاجر","سلسلة نباتات","وصفة طعام"],"عشب، أرنب، ثعلب.","السلسلة الغذائية تبيّن كيف تنتقل الطاقة من نبات إلى حيوان إلى حيوان.","المفترسات في القمة والنباتات في القاعدة دائمًا تقريبًا."]
      ]
